def count_equal(values, target):
    count = 0
    for value in values:
        if value == target:
            count += 1
    return count

print(count_equal([], 4))
print(count_equal([4], 4))
print(count_equal([4, 4], 4))
print(count_equal([3, 5], 4))

def count_pass_wrong(scores):
    count = 0
    for score in scores:
        if score > 80:
            count += 1
    return count

print(count_pass_wrong([90, 100]))
print(count_pass_wrong([80]))

